from base_sensor import BaseVirtualSensor

class INA3221_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16
    CONFIG_RESET = 0x7127
    MANUF_ID_RESET = 0x5449
    DIE_ID_RESET = 0x3220

    def __init__(self):
        super().__init__()
        self.regs = {i: 0 for i in range(256)}
        self.regs[0x00] = self.CONFIG_RESET
        self.regs[0xFE] = self.MANUF_ID_RESET
        self.regs[0xFF] = self.DIE_ID_RESET

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 1:
            return (self.regs[addr] & 0xFF00) >> 8
        else:
            return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data
